#!/bin/bash
# End-to-end smoke test of the lab sandbox, without a scan: build a tiny image locally (no push), commit
# an app that uses it to the output repository in the layout `containerizer org` writes (generated by
# containerizer from examples/ci-demo, smoke_app.py), let Flux deploy it, check that the pods are Ready
# and that nothing was pulled, then read it back with `containerizer sandbox verify` as the verifier.
#   smoke.sh            deploy and verify
#   smoke.sh --remove   take the app out of the output repository again (Flux prunes it)
. "$(dirname "$0")/lib.sh"
secrets
IMAGE=${SMOKE_IMAGE:-localhost/lab/smoke:1}
APP=smoke
out=$STATE/smoke-output
hdr=$(git_header "$LAB_GIT_WRITE_TOKEN")
g() { git -C "$out" -c "http.$GIT_URL.extraHeader=$hdr" -c user.name=containerizer \
        -c user.email=containerizer@users.noreply.invalid "$@"; }

if [ -d "$out/.git" ]; then g fetch -q origin main && g reset -q --hard origin/main
else git -c "http.$GIT_URL.extraHeader=$hdr" clone -q --branch main "$GIT_URL" "$out"; fi

if [ "${1:-}" = --remove ]; then
  [ -d "$out/lab/_/$APP" ] && find "$out/lab/_/$APP" -delete
  "$PY" -c 'import sys; from pathlib import Path; from containerizer.org import write_sandbox; write_sandbox(Path(sys.argv[1]), sys.argv[2], "main")' "$out" "$GIT_URL"
  g add -A && g commit -q -m "lab smoke test: remove $APP" && g push -q origin HEAD:main
  k -n flux-system annotate --overwrite gitrepository/containerizer-sandbox "reconcile.fluxcd.io/requestedAt=$(date +%s)" >/dev/null
  echo "removed $APP from the output repository; Flux prunes it within a minute"
  exit 0
fi

say "1. docker build -t $IMAGE (not pushed)"
docker build -q --build-arg BASE="$SMOKE_BASE" -t "$IMAGE" "$LAB_SCRIPTS/smoke" >/dev/null
docker image inspect "$IMAGE" --format '   {{.Id}}'

say "2. generate the app ($APP) into the output repository and push"
"$PY" "$LAB_SCRIPTS/smoke_app.py" "$out" "$GIT_URL" "$IMAGE" "$APP"
g add -A
if g diff --cached --quiet; then echo "   no change"; else g commit -q -m "lab smoke test: $APP ($IMAGE)" && g push -q origin HEAD:main; fi
rev=$(g rev-parse HEAD); echo "   revision $rev"

say "3. Flux: root sync, then the app's own GitRepository + Kustomization"
k -n flux-system annotate --overwrite gitrepository/containerizer-sandbox "reconcile.fluxcd.io/requestedAt=$(date +%s)" >/dev/null
k -n flux-system annotate --overwrite kustomization/containerizer-sandbox "reconcile.fluxcd.io/requestedAt=$(date +%s)" >/dev/null
for _ in $(seq 60); do k get ns "$APP" >/dev/null 2>&1 && k -n "$APP" get gitrepository "$APP" >/dev/null 2>&1 && break; sleep 5; done
"$LAB_SCRIPTS/sync.sh"            # the app's <ns>--cz-git, as the appliance's timer would within 2 minutes
k -n "$APP" annotate --overwrite gitrepository/"$APP" "reconcile.fluxcd.io/requestedAt=$(date +%s)" >/dev/null
k -n "$APP" wait --for=condition=Ready "kustomization.kustomize.toolkit.fluxcd.io/$APP" --timeout=600s
k -n "$APP" get kustomization "$APP" -o jsonpath='   applied {.status.lastAppliedRevision}{"\n"}'
k -n "$APP" get pods -o wide

say "4. no image was pulled"
k -n "$APP" get events --field-selector involvedObject.kind=Pod -o custom-columns=REASON:.reason,MESSAGE:.message --no-headers \
  | grep -E 'Pull|Pulled' | sort -u
if k -n "$APP" get events -o jsonpath='{range .items[*]}{.reason}{"\n"}{end}' | grep -qx Pulling; then
  echo "FAIL: a Pulling event: the image did not come from Docker's image store" >&2; exit 1
fi
echo "   no Pulling events"

say "5. containerizer sandbox verify, as the read-only verifier"
"$LAB_SCRIPTS/sync.sh"            # applies sandbox/verify-rbac.yaml and writes verifier.kubeconfig
(cd "$CZ_REPO" && "$PY" -m containerizer sandbox verify --output-dir "$out" --kubeconfig "$LAB_DIR/verifier.kubeconfig" \
  --revision "$rev" --timeout 300 --no-learn --fail-on-unhealthy)
